import pathlib
import subprocess
import sys
import tempfile
import unittest


SCRIPTS = pathlib.Path(__file__).resolve().parents[1]


class PhaseEvidenceTests(unittest.TestCase):
    def test_meryl_trough_uses_rounded_strict_boundary(self):
        with tempfile.TemporaryDirectory() as temp_dir:
            temp = pathlib.Path(temp_dir)
            (temp / "child.tsv").write_text(
                "noise-trough\t2.49\tploidy-peaks\t20\t40\t0\t0\n"
            )
            (temp / "maternal.tsv").write_text(
                "noise-trough\t2.50\tploidy-peaks\t20\t40\t0\t0\n"
            )
            (temp / "paternal.tsv").write_text(
                "noise-trough\t0.49\tploidy-peaks\t20\t40\t0\t0\n"
            )
            output = temp / "selected.tsv"
            subprocess.run(
                [
                    sys.executable, str(SCRIPTS / "select_marker_cutoffs.py"),
                    "--child-ploidy", str(temp / "child.tsv"),
                    "--maternal-ploidy", str(temp / "maternal.tsv"),
                    "--paternal-ploidy", str(temp / "paternal.tsv"),
                    "--output", str(output),
                ],
                check=True,
            )
            text = output.read_text()
            self.assertIn("child\t2\t2", text)
            self.assertIn("maternal\t3\t3", text)
            self.assertIn("paternal\t0\t0", text)

    def test_cutoff2_fallback(self):
        with tempfile.TemporaryDirectory() as temp_dir:
            temp = pathlib.Path(temp_dir)
            for name, trough in (("child", 4.2), ("maternal", 3.1), ("paternal", 8.1)):
                (temp / f"{name}.tsv").write_text(
                    f"noise-trough\t{trough}\tploidy-peaks\t20\t40\t0\t0\n"
                )
            (temp / "counts.tsv").write_text(
                "candidate\tmaternal\tpaternal\nauto\t1000\t100\ncutoff2\t900\t800\n"
            )
            output = temp / "selected.tsv"
            subprocess.run(
                [
                    sys.executable, str(SCRIPTS / "select_marker_cutoffs.py"),
                    "--child-ploidy", str(temp / "child.tsv"),
                    "--maternal-ploidy", str(temp / "maternal.tsv"),
                    "--paternal-ploidy", str(temp / "paternal.tsv"),
                    "--marker-counts", str(temp / "counts.tsv"),
                    "--output", str(output),
                ],
                check=True,
            )
            self.assertIn("selection\tcutoff2\tcutoff2", output.read_text())

    def test_contact_flip_and_fill(self):
        with tempfile.TemporaryDirectory() as temp_dir:
            temp = pathlib.Path(temp_dir)
            (temp / "graph.gfa").write_text(
                "S\ta\t*\tLN:i:100\nS\tb\t*\tLN:i:100\nS\tc\t*\tLN:i:100\n"
                "L\ta\t+\tb\t+\t0M\nL\tb\t+\tc\t+\t0M\n"
            )
            (temp / "parent.tsv").write_text(
                "node mat pat ratio color\na 100 0 100:0 red\nb 0 100 0:100 blue\n"
            )
            (temp / "contact.tsv").write_text(
                "node mat pat ratio color\na 0 100000 0:100000 blue\n"
                "b 100000 0 100000:0 red\nc 0 100000 0:100000 blue\n"
            )
            subprocess.run(
                [
                    sys.executable, str(SCRIPTS / "fuse_phase_evidence.py"),
                    "--graph", str(temp / "graph.gfa"),
                    "--parental", str(temp / "parent.tsv"),
                    "--contacts", str(temp / "contact.tsv"),
                    "--output", str(temp / "fused.tsv"),
                    "--report", str(temp / "report.tsv"),
                    "--conflicts", str(temp / "conflicts.tsv"),
                ],
                check=True,
            )
            rows = {line.split()[0]: line.split() for line in (temp / "fused.tsv").read_text().splitlines()[1:]}
            self.assertEqual(rows["a"][5:7], ["maternal", "parental+contacts"])
            self.assertEqual(rows["b"][5:7], ["paternal", "parental+contacts"])
            self.assertEqual(rows["c"][5:7], ["maternal", "contacts-fill"])
            self.assertEqual(rows["a"][4], "#FF8888")
            self.assertEqual(rows["b"][4], "#8888FF")
            self.assertIn("\t1\t1.000000", (temp / "report.tsv").read_text())


if __name__ == "__main__":
    unittest.main()
